import { useEffect, useState } from "react";
import axios from "axios";

export default function Perfil() {
  const [user, setUser] = useState(null);

  useEffect(() => {
    axios.get("http://localhost:3001/usuario")
      .then(res => setUser(res.data))
      .catch(() => alert("Erro ao carregar usuário."));
  }, []);

  if (!user) return <p>Carregando...</p>;

  return (
    <div className="card">
      <div className="card-body text-center">
        <img
          src={user.imagem}
          alt="Imagem"
          className="img-thumbnail mb-3"
          style={{ width: 150 }}
        />
        <h5 className="card-title">{user.nome}</h5>
        <p className="card-text">Idade: {user.idade}</p>
        <p className="card-text">Endereço: {user.rua}, {user.bairro} - {user.estado}</p>
        <p className="card-text"><strong>Biografia:</strong> {user.biografia}</p>
      </div>
    </div>
  );
}
